"use strict";(globalThis.webpackChunkdocs_that_speak=globalThis.webpackChunkdocs_that_speak||[]).push([[417],{3969(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"nextgen/ai-writes-the-draft","title":"AI Writes the Draft. You Write the Standard.","description":"The question is no longer whether AI will change technical writing. It already has. The question that matters now is: what does a technical writer own that AI cannot?","source":"@site/docs/nextgen/ai-writes-the-draft.md","sourceDirName":"nextgen","slug":"/nextgen/ai-writes-the-draft","permalink":"/DocsThatSpeak/docs/nextgen/ai-writes-the-draft","draft":false,"unlisted":false,"editUrl":"https://github.com/JKwrites-tech/DocsThatSpeak/edit/main/docs/nextgen/ai-writes-the-draft.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"id":"ai-writes-the-draft","title":"AI Writes the Draft. You Write the Standard.","sidebar_position":2},"sidebar":"nextgenSidebar","previous":{"title":"Overview","permalink":"/DocsThatSpeak/docs/nextgen/intro"},"next":{"title":"No One Reads Your Docs From the Top","permalink":"/DocsThatSpeak/docs/nextgen/no-one-reads-from-the-top"}}');var a=n(4848),s=n(8453);const r={id:"ai-writes-the-draft",title:"AI Writes the Draft. You Write the Standard.",sidebar_position:2},o="AI Writes the Draft. You Write the Standard.",d={},l=[{value:"What AI Is Actually Good At (And What It Isn&#39;t)",id:"what-ai-is-actually-good-at-and-what-it-isnt",level:2},{value:"Where AI Genuinely Saves Time",id:"where-ai-genuinely-saves-time",level:2},{value:"Building an AI-Assisted Workflow That Doesn&#39;t Compromise Trust",id:"building-an-ai-assisted-workflow-that-doesnt-compromise-trust",level:2},{value:"The Role That Gets Bigger, Not Smaller",id:"the-role-that-gets-bigger-not-smaller",level:2}];function h(e){const t={h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"ai-writes-the-draft-you-write-the-standard",children:"AI Writes the Draft. You Write the Standard."})}),"\n",(0,a.jsx)(t.p,{children:"The question is no longer whether AI will change technical writing. It already has. The question that matters now is: what does a technical writer own that AI cannot?"}),"\n",(0,a.jsx)(t.p,{children:"The answer is judgment \u2014 and judgment is not a soft skill. It is the most technically demanding part of the job."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"what-ai-is-actually-good-at-and-what-it-isnt",children:"What AI Is Actually Good At (And What It Isn't)"}),"\n",(0,a.jsx)(t.p,{children:"AI language models are remarkably good at producing fluent, well-structured prose quickly. They can generate a first draft of a procedure, expand a bullet list into paragraphs, suggest alternative phrasings, and produce boilerplate sections like introductions, summaries, and FAQs at a speed no human writer can match."}),"\n",(0,a.jsx)(t.p,{children:"What they are not good at is knowing whether any of it is true."}),"\n",(0,a.jsx)(t.p,{children:"This distinction \u2014 between fluency and accuracy \u2014 is the most important thing to understand about AI-assisted documentation. An AI model does not know your product. It does not know that your API changed in version 3.2, that the button label was renamed last sprint, or that step 4 in the procedure only applies to enterprise users. It will write confidently about all of these things anyway."}),"\n",(0,a.jsx)(t.p,{children:"This is not a criticism of AI \u2014 it is a description of what it is. AI generates plausible text based on patterns. Technical writers verify, contextualise, and take responsibility. Those are fundamentally different activities."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"where-ai-genuinely-saves-time",children:"Where AI Genuinely Saves Time"}),"\n",(0,a.jsx)(t.p,{children:"Used with discipline, AI can compress the most time-consuming parts of the documentation workflow significantly."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"First draft generation"})," \u2014 Feed AI a product specification, a JIRA ticket, or a feature description and ask it to produce a documentation draft structured as concept, task, and reference. You will get a usable starting structure in minutes instead of hours. The draft will need significant review \u2014 but you are editing, not starting from a blank page."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Terminology consistency"})," \u2014 AI can scan a large document set and flag inconsistencies in terminology, heading style, or tone. This is tedious work that humans do slowly and miss regularly."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Revision cycle reduction"})," \u2014 AI can act as a first-pass reviewer. Ask it to identify steps that are ambiguous, prerequisites that are unstated, or warnings that should be more prominent. You will catch a category of issues before the document reaches a human reviewer \u2014 reducing cycle time without reducing quality."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"FAQ generation"})," \u2014 Given an existing article, AI can generate a set of likely reader questions. Cross-reference these against your search failure data and you will quickly identify coverage gaps."]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"building-an-ai-assisted-workflow-that-doesnt-compromise-trust",children:"Building an AI-Assisted Workflow That Doesn't Compromise Trust"}),"\n",(0,a.jsx)(t.p,{children:"The biggest risk in AI-assisted documentation is not that AI will replace writers. It is that teams will use AI to produce content faster without investing equally in the verification infrastructure needed to keep it accurate."}),"\n",(0,a.jsx)(t.p,{children:"Documentation that is fast and wrong is worse than documentation that is slow and right. Users trust what they read. If they follow an AI-generated step that is outdated, incorrect, or contextually wrong, that trust breaks \u2014 and trust in documentation is remarkably hard to rebuild."}),"\n",(0,a.jsx)(t.p,{children:"A sustainable AI-assisted documentation workflow has four components:"}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"1. A subject matter expert review gate"})," \u2014 every AI-generated draft is reviewed by someone with direct product knowledge before it is published. This is not optional."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"2. A product-to-docs sync process"})," \u2014 documentation is updated as part of the same release workflow as the product change, not after. AI can help write the update; only a human can confirm it's correct."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"3. A style and standards layer"})," \u2014 your house style, terminology glossary, and content model are applied after AI generation. AI will not follow your standards unless you explicitly prompt it to \u2014 and even then, inconsistently."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"4. An accuracy audit cycle"})," \u2014 published AI-assisted content is reviewed on a defined schedule, not left to sit. Products change; AI-generated content doesn't update itself."]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-role-that-gets-bigger-not-smaller",children:"The Role That Gets Bigger, Not Smaller"}),"\n",(0,a.jsx)(t.p,{children:"Writers who understand how to prompt AI effectively, review its output critically, and build the quality infrastructure around it are not being automated \u2014 they are becoming more valuable."}),"\n",(0,a.jsx)(t.p,{children:"The documentation teams that will struggle are the ones that use AI to produce more content without building the systems to keep that content accurate. More content with lower trust is not a better outcome."}),"\n",(0,a.jsx)(t.p,{children:"The writers who thrive will be the ones who use AI to handle the mechanical parts of the job \u2014 drafting, formatting, consistency checking \u2014 and invest the time saved into the judgment-intensive work that AI cannot do: understanding the user, verifying the accuracy, and owning the quality bar."}),"\n",(0,a.jsx)(t.p,{children:"That is not a smaller job. It is a more strategic one."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var i=n(6540);const a={},s=i.createContext(a);function r(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);